function renderSexualityProgramFullTextHTML(sexualityProgram) {
  if (!sexualityProgram || !sexualityProgram.combination) return "";

  var data = sexualityProgramTexts[sexualityProgram.combination];

  if (!data || !data.text) {
    return "";
  }

  return '<div class="program-full-text energy-text">' +
    renderEnergyHTML(data.text) +
  '</div>';
}

