function renderSexualityProgramHTML(sexualityProgram) {
  if (!sexualityProgram || !sexualityProgram.name) {
    return '<div class="energy-item programs-card">' +
      '<h3>Program sexuality</h3>' +
      '<p>Pro kombinaci ' + escapeHtml(sexualityProgram.combination) + ' zatím není v databázi nahraný výklad.</p>' +
      '</div>';
  }

  var data = sexualityProgramTexts[sexualityProgram.combination];
  var displayName = data && data.title ? data.title : sexualityProgram.name;

  return '<div class="energy-item programs-card">' +
    '<h3>Program sexuality</h3>' +
    '<div class="program-found-item">' +
      '<div class="program-title">' +
        escapeHtml(displayName) +
        ' <span class="program-combination">(' + escapeHtml(sexualityProgram.combination) + ')</span>' +
      '</div>' +
      '<div class="program-repeat single">Nalezeno v centru matice</div>' +
      '<div class="program-zones">' +
        '<strong>Kde se objevuje:</strong><br>' +
        '• centrum matice: žlutý kruh a dva bílé kruhy doprava: ' + escapeHtml(sexualityProgram.foundCombination) +
      '</div>' +
      renderSexualityProgramFullTextHTML(sexualityProgram) +
    '</div>' +
  '</div>';
}
